MATCH (source:PlantItem)-[:send_to*1..]->(:Tank {tag: "TK-29902"})
WHERE NOT EXISTS {
  MATCH ()-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag

MATCH (item:PlantItem {tag: "EJ-504"})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (equipment:Equipment {tag: 'D-24901'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (f:FlameArrestor:PlantItem)
WHERE f.unit_id = '408'
RETURN count(f.tag) AS count, collect(f.tag) AS tags;

MATCH (item:PlantItem {tag: 'K-31201'})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (s:PlantItem {tag: 'D-35801'}), (t:PlantItem {tag: 'K-35801'})
RETURN s.tag AS source_tag, t.tag AS target_tag,
       EXISTS {
         MATCH p=(s)-[:send_to*1..]->(t)
         WHERE ALL(n IN nodes(p) WHERE n.tag IS NULL OR n.tag <> 'GV-358001')
       } AS can_flow_without_valve

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: "TK-54001"})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag
?

MATCH (:PlantItem {tag: "P-39301"})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem {tag: 'V-37801'}), (target:PlantItem {tag: 'P-37801'})
OPTIONAL MATCH path = (v)-[:send_to*]->(target)
RETURN v.tag AS source_tag, target.tag AS target_tag, path IS NOT NULL AS can_reach;

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: 'P-53601B'})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag eel

MATCH (equipment:Equipment {tag: 'E-48701'})-[:send_to]-(valve:PlantItem)<-[:control]-(:ActuatingFunction)<-[:send_signal_to]-(controller:ProcessControlFunction)
RETURN DISTINCT controller.tag AS tag
ORDER BY tag;

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: "TK-37402"})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag

MATCH (e:PlantItem {tag: 'EH-48101'})-[:send_to]-(v:PlantItem)<-[:control]-(a:PlantItem)<-[:send_signal_to]-(c:PlantItem)
RETURN DISTINCT c.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:GlobeValve)
WHERE v.unit_id = '353'
RETURN collect(DISTINCT v.tag) AS tags, count(DISTINCT v) AS count;

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: "P-11401"})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag	final

MATCH (source:PlantItem {tag: 'P-60503'})-[:send_to*1..]->(item:PlantItem)
WHERE item.unit_id IS NOT NULL AND item.unit_id <> source.unit_id
RETURN count(DISTINCT item.unit_id) AS other_unit_count;

MATCH p=(s:PlantItem {tag: "E-15604"})-[:send_to*1..]->(t:PlantItem {tag: "P-15801B"})
RETURN [n IN nodes(p) | n.tag] AS path_tags
LIMIT 1;

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: "F-301"})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag
ORDER BY tag

MATCH (source:PlantItem)-[:send_to*1..]->(:PlantItem {tag: "E-701"})
WHERE NOT EXISTS { MATCH ()-[:send_to]->(source) }
RETURN DISTINCT source.tag AS tag;

MATCH p = (s:PlantItem {tag: 'D-44801'})-[:send_to*]->(t:PlantItem {tag: 'P-59606'})
WHERE all(n IN nodes(p) WHERE coalesce(n.tag, '') <> 'BFV-492002')
RETURN [n IN nodes(p) | n.tag] AS path_tags, true AS can_flow;

MATCH (start:PlantItem {tag: 'D-6101'}), (finish:PlantItem {tag: 'E-504'})
MATCH p = shortestPath((start)-[:send_to*]->(finish))
RETURN [n IN nodes(p) WHERE 'Equipment' IN labels(n) OR any(label IN labels(n) WHERE label IN ['AngleBallValve', 'AngleGlobeValve', 'AnglePlugValve', 'AngleValve', 'BallValve', 'BreatherValve', 'ButterflyValve', 'CheckValve', 'GateValve', 'GlobeCheckValve', 'GlobeValve', 'NeedleValve', 'OperatedValve', 'PlugValve', 'SafetyValveOrFitting', 'SpringLoadedAngleGlobeSafetyValve', 'SpringLoadedGlobeSafetyValve', 'SwingCheckValve', 'StraightwayValve']) | n.tag] AS flow_path_tags;

MATCH (item:PlantItem {tag: "EJ-504"})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: "K-31201"})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;
